import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import { validator } from "./schemas.mjs";

// SCHEMA.md <!-- schema: views -->: an item's views[] (generated by tools/gen_views.py; tests/test_views.py checks it is fresh)
const validate = validator("views");

test("views: good entries validate", () => {
  const v = [{ stage: "pre", recipe: "hint-line", src: "root = View([t])\nt = Text(\"hi\")" },
             { stage: "wrong:misread", recipe: "misconception", src: "root = View([])", lib: "0.1.0" }];
  assert.ok(validate(v), JSON.stringify(validate.errors));
});

test("views: bad stage, unknown recipe, empty src, unknown key fail", () => {
  for (const bad of [{ stage: "wrong", recipe: "steps", src: "x" }, { stage: "pre", recipe: "nope", src: "x" },
                     { stage: "pre", recipe: "steps", src: "" }, { stage: "pre", recipe: "steps", src: "x", extra: 1 }])
    assert.equal(validate([bad]), false, JSON.stringify(bad));
});

// views/library.json against the vendored OpenUI parser (P0.4, vendor/openui-lang.mjs); skipped until that file exists
const vendor = new URL("../vendor/openui-lang.mjs", import.meta.url);
test("library.json: the vendored prompt generator and parser take it", { skip: !existsSync(vendor) && "vendor/openui-lang.mjs not here yet (P0.4)" }, async () => {
  const { generateSystemPrompt, createParser } = await import(vendor);
  const lib = JSON.parse(readFileSync(new URL("../views/library.json", import.meta.url), "utf8"));
  const prompt = generateSystemPrompt({ library: lib });   // prints components[].signature under each componentGroups heading
  for (const g of lib.componentGroups) assert.ok(prompt.includes(`### ${g.name}\n`), g.name);
  for (const [name, c] of Object.entries(lib.components)) assert.ok(prompt.includes(`${c.signature} — ${c.description}`), name);
  const r = createParser(lib.schema, lib.root).parse('root = View([s, d])\ns = Steps(g, [a])\ng = Graph("A 48 100, B 160 48", "A-B")\na = Step("Lock A", "A:done B:front")\nd = Doodle("duck")');
  assert.equal(r.root.typeName, "View");
  assert.deepEqual(r.meta.errors ?? [], []);
});
